@Composable
fun AncApp(ancViewModel: AncViewModel = viewModel()) {
  val uiState by ancViewModel.uiState.collectAsState()

  BackHandler(enabled = uiState.currentScreen != Screen.Register) {
    ancViewModel.navigateBack()
  }

  when (val screen = uiState.currentScreen) {
    Screen.Register -> {
      RegisterScreen(
        patients = uiState.patients,
        isLoading = uiState.isLoading,
        isSyncing = uiState.isSyncing,
        errorMessage = uiState.errorMessage,
        onRefresh = { ancViewModel.refresh() },
        onPatientClick = { patientId -> ancViewModel.openPatientDetail(patientId) },
      )
    }

    is Screen.PatientDetail -> {
      val detail =
        uiState.selectedPatientDetail?.takeIf { it.patient.id == screen.patientId }
      PatientDetailScreen(
        patientDetail = detail,
        isSyncing = uiState.isSyncing,
        onBack = { ancViewModel.navigateBack() },
        onRecordNewVisit = { ancViewModel.openNewVisitForm(screen.patientId) },
      )
    }

    is Screen.NewVisit -> {
      val patientName =
        uiState.selectedPatientDetail?.patient?.name
          ?: uiState.patients.find { it.id == screen.patientId }?.name
          ?: "Patient"
      val questionnaireJson = uiState.questionnaireJson
      if (questionnaireJson != null) {
        NewAncVisitScreen(
          patientId = screen.patientId,
          patientName = patientName,
          questionnaireJson = questionnaireJson,
          isSaving = uiState.isSaving,
          onSave = { response -> ancViewModel.saveVisit(screen.patientId, response) },
          onCancel = { ancViewModel.navigateBack() },
        )
      } else {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
          CircularProgressIndicator()
        }
      }
    }
  }
}

