              fontWeight = FontWeight.SemiBold,
              color = MaterialTheme.colorScheme.onSecondaryContainer,
              modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
            )
          }
        }
      }

      HorizontalDivider()

      FlowRow(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
      ) {
        if (visit.weight != null) {
          VisitMetricItem(
            label = "Weight",
            value = visit.weight,
            icon = Icons.Default.MonitorWeight,
          )
        }
        if (visit.bloodPressure != null) {
          VisitMetricItem(
            label = "Blood Pressure",
            value = visit.bloodPressure,
            icon = Icons.Default.Favorite,
          )
        }
        if (visit.hemoglobin != null) {
          VisitMetricItem(
            label = "Hemoglobin (Hb)",
            value = visit.hemoglobin,
          )
        }
      }

      if (visit.dangerSigns.isNotEmpty()) {
        val hasActualDanger =
          visit.dangerSigns.any { !it.equals("None", ignoreCase = true) && !it.equals("none", ignoreCase = true) }
        Row(
          verticalAlignment = Alignment.CenterVertically,
          horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
          if (hasActualDanger) {
            Icon(
              imageVector = Icons.Default.Warning,
              contentDescription = null,
              tint = MaterialTheme.colorScheme.error,
              modifier = Modifier.size(16.dp),
            )
          }
          Text(
            text = "Danger signs: ${visit.dangerSigns.joinToString(", ")}",
            style = MaterialTheme.typography.bodyMedium,
            color =
              if (hasActualDanger) {
                MaterialTheme.colorScheme.error
              } else {
                MaterialTheme.colorScheme.onSurfaceVariant
              },
            fontWeight = if (hasActualDanger) FontWeight.SemiBold else FontWeight.Normal,
          )
        }
      }

      if (!visit.notes.isNullOrBlank()) {
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
      }
    }
  }
}

