/**
 * Tracks the active [QuestionnaireResponse.Item]s across the form so that either the top-bar Save
 * action or the bottom-bar Submit button can construct the current [QuestionnaireResponse]
 * without any input debounce delay.
 */
class AncFormStateHolder {
  private val responseItemsByLinkId = LinkedHashMap<String, QuestionnaireResponse.Item>()

  fun registerItem(viewItem: QuestionnaireViewItem) {
    val linkId = viewItem.questionnaireItem.linkId.value ?: return
    responseItemsByLinkId[linkId] = viewItem.getQuestionnaireResponseItem()
  }

  fun buildQuestionnaireResponse(): QuestionnaireResponse =
    QuestionnaireResponse(
      status = Enumeration(value = QuestionnaireResponse.QuestionnaireResponseStatus.Completed),
      item = responseItemsByLinkId.values.toList(),
    )
}

class CustomQuestionnaireMatchersProvider(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactoryMatchersProvider {

  override fun get(): List<QuestionnaireItemViewFactoryMatcher> =
    listOf(
      QuestionnaireItemViewFactoryMatcher(
        factory = ImmediateGroupViewFactory(formStateHolder),
        matches = { item -> item.type.value == Questionnaire.QuestionnaireItemType.Group },
      ),
      QuestionnaireItemViewFactoryMatcher(
        factory = ImmediateDateViewFactory(formStateHolder),
        matches = { item -> item.type.value == Questionnaire.QuestionnaireItemType.Date },
      ),
      QuestionnaireItemViewFactoryMatcher(
        factory = ImmediateIntegerViewFactory(formStateHolder),
        matches = { item -> item.type.value == Questionnaire.QuestionnaireItemType.Integer },
      ),
      QuestionnaireItemViewFactoryMatcher(
        factory = ImmediateDecimalViewFactory(formStateHolder),
        matches = { item -> item.type.value == Questionnaire.QuestionnaireItemType.Decimal },
      ),
      QuestionnaireItemViewFactoryMatcher(
        factory = ImmediateChoiceViewFactory(formStateHolder),
        matches = { item -> item.type.value == Questionnaire.QuestionnaireItemType.Choice },
      ),
      QuestionnaireItemViewFactoryMatcher(
        factory = ImmediateTextViewFactory(formStateHolder),
        matches = { item ->
          item.type.value == Questionnaire.QuestionnaireItemType.Text ||
            item.type.value == Questionnaire.QuestionnaireItemType.String
        },
      ),
    )
}

private class ImmediateGroupViewFactory(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactory {
  @Composable
  override fun Content(questionnaireViewItem: QuestionnaireViewItem) {
    SideEffect { formStateHolder.registerItem(questionnaireViewItem) }
    val labelText =
      questionnaireViewItem.questionnaireItem.text?.value
        ?: questionnaireViewItem.questionText?.text
        ?: ""
    if (labelText.isNotBlank()) {
      Text(
        text = labelText,
        style = MaterialTheme.typography.titleSmall,
        fontWeight = FontWeight.SemiBold,
        color = MaterialTheme.colorScheme.primary,
        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 2.dp),
      )
    }
  }
}

private class ImmediateDateViewFactory(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactory {

  @OptIn(ExperimentalMaterial3Api::class)
  @Composable
  override fun Content(questionnaireViewItem: QuestionnaireViewItem) {
    SideEffect { formStateHolder.registerItem(questionnaireViewItem) }
    val currentViewItem by rememberUpdatedState(questionnaireViewItem)
    val coroutineScope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current
    val linkId = questionnaireViewItem.questionnaireItem.linkId.value ?: "visit-date"
    val labelText =
      questionnaireViewItem.questionnaireItem.text?.value
        ?: questionnaireViewItem.questionText?.text
        ?: "Visit date"

    var textValue by
      remember(linkId) {
        val existingIso =
          questionnaireViewItem.answers
            .firstOrNull()
            ?.value
            ?.asDate()
            ?.value
            ?.value
            ?.toString()
            ?: (questionnaireViewItem.draftAnswer as? String)
            ?: ""
        mutableStateOf(existingIso)
      }

    var showDatePicker by remember(linkId) { mutableStateOf(false) }

    val applyDateInput: (String) -> Unit = { rawInput ->
      textValue = rawInput
      val trimmed = rawInput.trim()
      val parsedIso = parseFlexibleDateToIso(trimmed)
      coroutineScope.launch(start = CoroutineStart.UNDISPATCHED) {
        if (parsedIso != null) {
          val fhirDate = FhirDate.fromString(parsedIso)
          if (fhirDate != null) {
            currentViewItem.setAnswer(
              QuestionnaireResponse.Item.Answer(
                value = QuestionnaireResponse.Item.Answer.Value.Date(Date(value = fhirDate))
              )
            )
          }
        } else if (trimmed.isEmpty()) {
          currentViewItem.clearAnswer()
        } else {
          currentViewItem.setDraftAnswer(trimmed)
        }
      }
    }

    val isInvalid = questionnaireViewItem.validationResult is Invalid
    val errorMsg =
      (questionnaireViewItem.validationResult as? Invalid)?.singleStringValidationMessage

    Column(
      modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 2.dp),
    ) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        OutlinedTextField(
          value = textValue,
          onValueChange = applyDateInput,
          label = { Text(labelText) },
          placeholder = { Text("YYYY-MM-DD") },
          singleLine = true,
          isError = isInvalid,
          supportingText =
            if (isInvalid && !errorMsg.isNullOrBlank()) {
              { Text(errorMsg) }
            } else {
              null
            },
          keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
          keyboardActions = KeyboardActions(onDone = { focusManager.clearFocus() }),
          trailingIcon = {
            IconButton(onClick = { showDatePicker = true }) {
              Icon(
                imageVector = Icons.Default.CalendarToday,
                contentDescription = "Select date",
              )
            }
          },
          modifier = Modifier.weight(1f).testTag(linkId),
        )
        Spacer(modifier = Modifier.width(8.dp))
        AssistChip(
          onClick = {
            focusManager.clearFocus()
            applyDateInput(LocalDate.now().toString())
          },
          label = { Text("Today") },
        )
      }
    }

    if (showDatePicker) {
      val initialMillis =
        remember(textValue) {
          val parsed = parseFlexibleDateToIso(textValue.trim())
          val date =
            try {
              if (parsed != null) LocalDate.parse(parsed) else LocalDate.now()
            } catch (_: Exception) {
              LocalDate.now()
            }
          date.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli()
        }
      val datePickerState = rememberDatePickerState(initialSelectedDateMillis = initialMillis)
      DatePickerDialog(
        onDismissRequest = { showDatePicker = false },
        confirmButton = {
          TextButton(
            onClick = {
              datePickerState.selectedDateMillis?.let { millis ->
                val selectedDate =
                  Instant.ofEpochMilli(millis).atZone(ZoneOffset.UTC).toLocalDate()
                applyDateInput(selectedDate.toString())
              }
              showDatePicker = false
            }
          ) {
            Text("OK")
          }
        },
        dismissButton = {
          TextButton(onClick = { showDatePicker = false }) { Text("Cancel") }
        },
      ) {
        DatePicker(state = datePickerState)
      }
    }
  }
}

private class ImmediateIntegerViewFactory(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactory {

  @Composable
  override fun Content(questionnaireViewItem: QuestionnaireViewItem) {
    SideEffect { formStateHolder.registerItem(questionnaireViewItem) }
    val currentViewItem by rememberUpdatedState(questionnaireViewItem)
    val coroutineScope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current
    val linkId = questionnaireViewItem.questionnaireItem.linkId.value ?: "integer-field"
    val labelText =
      questionnaireViewItem.questionnaireItem.text?.value
        ?: questionnaireViewItem.questionText?.text
        ?: linkId

    var textValue by
      remember(linkId) {
        val existing =
          questionnaireViewItem.answers
            .firstOrNull()
            ?.value
            ?.asInteger()
            ?.value
            ?.value
            ?.toString()
            ?: (questionnaireViewItem.draftAnswer as? String)
            ?: ""
        mutableStateOf(existing)
      }

    val isInvalid = questionnaireViewItem.validationResult is Invalid
    val errorMsg =
      (questionnaireViewItem.validationResult as? Invalid)?.singleStringValidationMessage

    Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 2.dp)) {
      OutlinedTextField(
        value = textValue,
        onValueChange = { rawInput ->
          val cleaned = rawInput.filter { it.isDigit() }
          textValue = cleaned
          val intVal = cleaned.toIntOrNull()
          coroutineScope.launch(start = CoroutineStart.UNDISPATCHED) {
            if (intVal != null) {
              currentViewItem.setAnswer(
                QuestionnaireResponse.Item.Answer(
                  value =
                    QuestionnaireResponse.Item.Answer.Value.Integer(FhirInteger(value = intVal))
                )
              )
            } else {
              currentViewItem.clearAnswer()
            }
          }
        },
        label = { Text(labelText) },
        singleLine = true,
        isError = isInvalid,
        supportingText =
          if (isInvalid && !errorMsg.isNullOrBlank()) {
            { Text(errorMsg) }
          } else {
            null
          },
        keyboardOptions =
          KeyboardOptions(
            keyboardType = KeyboardType.Number,
            imeAction = ImeAction.Done,
          ),
        keyboardActions = KeyboardActions(onDone = { focusManager.clearFocus() }),
        modifier = Modifier.fillMaxWidth().testTag(linkId),
      )
    }
  }
}

private class ImmediateDecimalViewFactory(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactory {

  @Composable
  override fun Content(questionnaireViewItem: QuestionnaireViewItem) {
    SideEffect { formStateHolder.registerItem(questionnaireViewItem) }
    val currentViewItem by rememberUpdatedState(questionnaireViewItem)
    val coroutineScope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current
    val linkId = questionnaireViewItem.questionnaireItem.linkId.value ?: "decimal-field"
    val labelText =
      questionnaireViewItem.questionnaireItem.text?.value
        ?: questionnaireViewItem.questionText?.text
        ?: linkId

    var textValue by
      remember(linkId) {
        val existing =
          questionnaireViewItem.answers
            .firstOrNull()
            ?.value
            ?.asDecimal()
            ?.value
            ?.value
            ?.toStringExpanded()
            ?: (questionnaireViewItem.draftAnswer as? String)
            ?: ""
        mutableStateOf(existing)
      }

    val isInvalid = questionnaireViewItem.validationResult is Invalid
    val errorMsg =
      (questionnaireViewItem.validationResult as? Invalid)?.singleStringValidationMessage

    Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 2.dp)) {
      OutlinedTextField(
        value = textValue,
        onValueChange = { rawInput ->
          val cleaned = buildString {
            var dotSeen = false
            for (c in rawInput) {
              if (c.isDigit()) {
                append(c)
              } else if (c == '.' && !dotSeen) {
                append(c)
                dotSeen = true
              }
            }
          }
          textValue = cleaned
          val trimmed = cleaned.trimEnd('.')
          val parsedDecimal =
            try {
              if (trimmed.isNotEmpty()) BigDecimal.parseString(trimmed) else null
            } catch (_: Exception) {
              null
            }
          coroutineScope.launch(start = CoroutineStart.UNDISPATCHED) {
            if (parsedDecimal != null) {
              currentViewItem.setAnswer(
                QuestionnaireResponse.Item.Answer(
                  value =
                    QuestionnaireResponse.Item.Answer.Value.Decimal(Decimal(value = parsedDecimal))
                )
              )
            } else {
              currentViewItem.clearAnswer()
            }
          }
        },
        label = { Text(labelText) },
        singleLine = true,
        isError = isInvalid,
        supportingText =
          if (isInvalid && !errorMsg.isNullOrBlank()) {
            { Text(errorMsg) }
          } else {
            null
          },
        keyboardOptions =
          KeyboardOptions(
            keyboardType = KeyboardType.Decimal,
            imeAction = ImeAction.Done,
          ),
        keyboardActions = KeyboardActions(onDone = { focusManager.clearFocus() }),
        modifier = Modifier.fillMaxWidth().testTag(linkId),
      )
    }
  }
}

private class ImmediateChoiceViewFactory(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactory {

  @Composable
  override fun Content(questionnaireViewItem: QuestionnaireViewItem) {
    SideEffect { formStateHolder.registerItem(questionnaireViewItem) }
    val currentViewItem by rememberUpdatedState(questionnaireViewItem)
    val coroutineScope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current
    val linkId = questionnaireViewItem.questionnaireItem.linkId.value ?: "choice-field"
    val labelText =
      questionnaireViewItem.questionnaireItem.text?.value
        ?: questionnaireViewItem.questionText?.text
        ?: "Danger signs present"

    val options: List<Coding> =
      remember(questionnaireViewItem.enabledAnswerOptions) {
        questionnaireViewItem.enabledAnswerOptions.mapNotNull { it.value.asCoding()?.value }
      }

    var selectedCodes by
      remember(linkId) {
        val initialCodes =
          questionnaireViewItem.answers
            .mapNotNull { it.value?.asCoding()?.value?.code?.value }
            .toSet()
        mutableStateOf(initialCodes)
      }

    Column(
      modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 2.dp),
      verticalArrangement = Arrangement.spacedBy(2.dp),
    ) {
      Text(
        text = labelText,
        style = MaterialTheme.typography.titleSmall,
        fontWeight = FontWeight.SemiBold,
        color = MaterialTheme.colorScheme.primary,
      )

      options.chunked(2).forEach { rowOptions ->
        Row(
          modifier = Modifier.fillMaxWidth(),
          horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
          rowOptions.forEach { coding ->
            val codeStr = coding.code?.value ?: ""
            val displayStr = coding.display?.value ?: codeStr
            val isSelected = codeStr in selectedCodes

            Surface(
              shape = RoundedCornerShape(6.dp),
              color =
                if (isSelected) {
                  MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.6f)
                } else {
                  MaterialTheme.colorScheme.surface
                },
              modifier =
                Modifier.weight(1f)
                  .toggleable(
                    value = isSelected,
                    role = Role.Checkbox,
                    onValueChange = { checked ->
                      focusManager.clearFocus()
                      val updatedCodes =
                        if (checked) {
                          if (codeStr == "none") {
                            setOf("none")
                          } else {
                            (selectedCodes - "none") + codeStr
                          }
                        } else {
                          selectedCodes - codeStr
                        }
                      selectedCodes = updatedCodes
                      val newAnswers =
                        options
                          .filter { (it.code?.value ?: "") in updatedCodes }
                          .map { selectedCoding ->
                            QuestionnaireResponse.Item.Answer(
                              value = QuestionnaireResponse.Item.Answer.Value.Coding(selectedCoding)
                            )
                          }
                      coroutineScope.launch(start = CoroutineStart.UNDISPATCHED) {
                        if (newAnswers.isEmpty()) {
                          currentViewItem.clearAnswer()
                        } else {
                          currentViewItem.setAnswer(*newAnswers.toTypedArray())
                        }
                      }
                    },
                  )
                  .testTag("danger_sign_$codeStr"),
            ) {
              Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 6.dp, vertical = 6.dp),
                verticalAlignment = Alignment.CenterVertically,
              ) {
                Checkbox(checked = isSelected, onCheckedChange = null)
                Spacer(modifier = Modifier.width(6.dp))
                Text(
                  text = displayStr,
                  style = MaterialTheme.typography.bodyMedium,
                )
              }
            }
          }
          if (rowOptions.size == 1) {
            Spacer(modifier = Modifier.weight(1f))
          }
        }
      }
    }
  }
}

private class ImmediateTextViewFactory(
  private val formStateHolder: AncFormStateHolder,
) : QuestionnaireItemViewFactory {

  @Composable
  override fun Content(questionnaireViewItem: QuestionnaireViewItem) {
    SideEffect { formStateHolder.registerItem(questionnaireViewItem) }
    val currentViewItem by rememberUpdatedState(questionnaireViewItem)
    val coroutineScope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current
    val linkId = questionnaireViewItem.questionnaireItem.linkId.value ?: "notes"
    val labelText =
      questionnaireViewItem.questionnaireItem.text?.value
        ?: questionnaireViewItem.questionText?.text
        ?: "Notes"

    var textValue by
      remember(linkId) {
        val existing =
          questionnaireViewItem.answers
            .firstOrNull()
            ?.value
            ?.asString()
            ?.value
            ?.value
            ?: ""
        mutableStateOf(existing)
      }

    Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 2.dp)) {
      OutlinedTextField(
        value = textValue,
        onValueChange = { rawInput ->
          textValue = rawInput
          coroutineScope.launch(start = CoroutineStart.UNDISPATCHED) {
            if (rawInput.isBlank()) {
              currentViewItem.clearAnswer()
            } else {
              currentViewItem.setAnswer(
                QuestionnaireResponse.Item.Answer(
                  value = QuestionnaireResponse.Item.Answer.Value.String(FhirString(value = rawInput))
                )
              )
            }
          }
        },
        label = { Text(labelText) },
        singleLine = true,
        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
        keyboardActions = KeyboardActions(onDone = { focusManager.clearFocus() }),
        modifier = Modifier.fillMaxWidth().testTag(linkId),
      )
    }
  }
}

internal fun parseFlexibleDateToIso(input: String): String? {
  if (input.isBlank()) return null
  // Direct ISO yyyy-MM-dd
  try {
    return LocalDate.parse(input, DateTimeFormatter.ISO_LOCAL_DATE).toString()
  } catch (_: Exception) {}

  // yyyy-M-d or yyyy/M/d
  val dashOrSlashParts = input.split('-', '/')
  if (dashOrSlashParts.size == 3) {
    val p0 = dashOrSlashParts[0].toIntOrNull()
    val p1 = dashOrSlashParts[1].toIntOrNull()
    val p2 = dashOrSlashParts[2].toIntOrNull()
    if (p0 != null && p1 != null && p2 != null) {
      try {
        if (p0 > 1900) {
          return LocalDate.of(p0, p1, p2).toString()
        } else if (p2 > 1900) {
          // MM/dd/yyyy or dd/MM/yyyy
          return if (p0 > 12) {
            LocalDate.of(p2, p1, p0).toString()
          } else {
            LocalDate.of(p2, p0, p1).toString()
          }
        }
      } catch (_: Exception) {}
    }
  }
  return null
}

